pragma solidity ^0.8.24;

contract CounterPlus {
    uint256 public count;
    address public immutable owner;

    event Changed(address indexed by, uint256 newValue);

    constructor() {
        owner = msg.sender;
    }

    function inc() public {
        count += 1;
        emit Changed(msg.sender, count);
    }

    function dec() public {
        require(count > 0, "count gia' a zero");
        count -= 1;
        emit Changed(msg.sender, count);
    }

    function reset() public {
        require(msg.sender == owner, "solo il proprietario");
        count = 0;
        emit Changed(msg.sender, 0);
    }
}

