// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

contract Vault {
    address public immutable creator;
    address public immutable holder;

    constructor(address _holder) payable {
        creator = msg.sender;
        holder = _holder;
    }
}

contract VaultFactory {
    Vault[] public vaults;
    event VaultCreated(address indexed holder, address vault, uint256 index);

    function createVault(address holder) external payable returns (Vault v) {
        v = new Vault{value: msg.value}(holder);
        vaults.push(v);
        emit VaultCreated(holder, address(v), vaults.length - 1);
    }

    function count() external view returns (uint256) {
        return vaults.length;
    }

    // Indirizzo CREATE: ultimi 20 byte di keccak256(rlp([address(this), nonce])).
    // Il nonce di un contratto parte da 1 (EIP-161); valido per 1 <= nonce <= 0x7f.
    function predict(uint256 nonce) public view returns (address) {
        require(nonce >= 1 && nonce <= 0x7f, "nonce fuori range");
        bytes32 hsh = keccak256(abi.encodePacked(bytes1(0xd6), bytes1(0x94), address(this), bytes1(uint8(nonce))));
        return address(uint160(uint256(hsh)));
    }
}

