// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

contract SafeCrowdFunding {
    struct Campaign {
        address payable beneficiary;
        uint256 goal;
        uint256 deadline;   // numero di blocco
        uint256 amount;
        bool claimed;
        mapping(address => uint256) given;
    }

    uint256 public numCampaigns;
    mapping(uint256 => Campaign) private campaigns;

    event Contributed(uint256 indexed id, address indexed from, uint256 value);
    event Claimed(uint256 indexed id, uint256 amount);
    event Refunded(uint256 indexed id, address indexed to, uint256 value);

    modifier exists(uint256 id) {
        require(id < numCampaigns, "campagna inesistente");
        _;
    }

    function newCampaign(address payable beneficiary, uint256 goal, uint256 durationBlocks)
        external returns (uint256 id)
    {
        require(beneficiary != address(0), "beneficiario nullo");
        require(goal > 0 && durationBlocks > 0, "parametri non validi");
        id = numCampaigns++;
        Campaign storage c = campaigns[id];
        c.beneficiary = beneficiary;
        c.goal = goal;
        c.deadline = block.number + durationBlocks;
    }

    function contribute(uint256 id) external payable exists(id) {
        Campaign storage c = campaigns[id];
        require(block.number < c.deadline, "campagna chiusa");
        require(msg.value > 0, "niente valore");
        c.given[msg.sender] += msg.value;
        c.amount += msg.value;
        emit Contributed(id, msg.sender, msg.value);
    }

    function claim(uint256 id) external exists(id) {
        Campaign storage c = campaigns[id];
        require(c.amount >= c.goal, "obiettivo non raggiunto");
        require(!c.claimed, "gia' riscosso");
        c.claimed = true;                        // effects prima della interaction
        (bool ok, ) = c.beneficiary.call{value: c.amount}("");
        require(ok, "trasferimento fallito");    // se fallisce, revert: stato ripristinato
        emit Claimed(id, c.amount);
    }

    function refund(uint256 id) external exists(id) {
        Campaign storage c = campaigns[id];
        require(block.number >= c.deadline, "campagna ancora aperta");
        require(c.amount < c.goal, "obiettivo raggiunto");
        uint256 v = c.given[msg.sender];
        require(v > 0, "nulla da rimborsare");
        c.given[msg.sender] = 0;                 // azzero prima di inviare
        (bool ok, ) = payable(msg.sender).call{value: v}("");
        require(ok, "rimborso fallito");
        emit Refunded(id, msg.sender, v);
    }
}

