// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

struct AddrMap {
    mapping(address => uint256) value;
    mapping(address => uint256) pos;   // posizione in keys + 1 (0 = assente)
    address[] keys;
}

library AddrMapLib {
    function set(AddrMap storage m, address k, uint256 v) internal returns (bool isNew) {
        m.value[k] = v;
        if (m.pos[k] != 0) return false;
        m.keys.push(k);
        m.pos[k] = m.keys.length;
        return true;
    }

    function remove(AddrMap storage m, address k) internal returns (bool) {
        uint256 p = m.pos[k];
        if (p == 0) return false;
        uint256 last = m.keys.length;
        if (p != last) {                       // sposta l'ultima chiave nel buco
            address moved = m.keys[last - 1];
            m.keys[p - 1] = moved;
            m.pos[moved] = p;
        }
        m.keys.pop();
        delete m.pos[k];
        delete m.value[k];
        return true;
    }

    function length(AddrMap storage m) internal view returns (uint256) {
        return m.keys.length;
    }

    function at(AddrMap storage m, uint256 i) internal view returns (address k, uint256 v) {
        k = m.keys[i];
        v = m.value[k];
    }
}

contract Registry {
    using AddrMapLib for AddrMap;
    AddrMap private m;

    function set(address k, uint256 v) external returns (bool) { return m.set(k, v); }
    function remove(address k) external returns (bool) { return m.remove(k); }
    function length() external view returns (uint256) { return m.length(); }

    function sum() external view returns (uint256 s) {
        for (uint256 i = 0; i < m.length(); i++) {
            (, uint256 v) = m.at(i);
            s += v;
        }
    }
}

